import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import RiskOpportunityHeatmap from './components/RiskOpportunityHeatmap';
import DataManager from './components/DataManager';
import FilterPanel from './components/FilterPanel';
import ExportPanel from './components/ExportPanel';
import { generateSampleData } from './utils/sampleData';

function App() {
  const [items, setItems] = useState([]);
  const [filteredItems, setFilteredItems] = useState([]);
  const [filters, setFilters] = useState({
    category: 'all',
    riskLevel: 'all',
    opportunityLevel: 'all',
    searchTerm: ''
  });
  const [showDataManager, setShowDataManager] = useState(false);
  const [editingItem, setEditingItem] = useState(null);

  // Load sample data on first render
  useEffect(() => {
    const savedData = localStorage.getItem('riskOpportunityData');
    if (savedData) {
      setItems(JSON.parse(savedData));
    } else {
      const sampleData = generateSampleData();
      setItems(sampleData);
      localStorage.setItem('riskOpportunityData', JSON.stringify(sampleData));
    }
  }, []);

  // Apply filters
  useEffect(() => {
    let filtered = items;

    if (filters.category !== 'all') {
      filtered = filtered.filter(item => item.category === filters.category);
    }

    if (filters.riskLevel !== 'all') {
      filtered = filtered.filter(item => item.riskLevel === filters.riskLevel);
    }

    if (filters.opportunityLevel !== 'all') {
      filtered = filtered.filter(item => item.opportunityLevel === filters.opportunityLevel);
    }

    if (filters.searchTerm) {
      filtered = filtered.filter(item => 
        item.title.toLowerCase().includes(filters.searchTerm.toLowerCase()) ||
        item.description.toLowerCase().includes(filters.searchTerm.toLowerCase())
      );
    }

    setFilteredItems(filtered);
  }, [items, filters]);

  const handleAddItem = (item) => {
    const newItem = {
      ...item,
      id: Date.now().toString(),
      createdAt: new Date().toISOString()
    };
    const updatedItems = [...items, newItem];
    setItems(updatedItems);
    localStorage.setItem('riskOpportunityData', JSON.stringify(updatedItems));
    setShowDataManager(false);
  };

  const handleUpdateItem = (updatedItem) => {
    const updatedItems = items.map(item => 
      item.id === updatedItem.id ? { ...updatedItem, updatedAt: new Date().toISOString() } : item
    );
    setItems(updatedItems);
    localStorage.setItem('riskOpportunityData', JSON.stringify(updatedItems));
    setEditingItem(null);
    setShowDataManager(false);
  };

  const handleDeleteItem = (itemId) => {
    const updatedItems = items.filter(item => item.id !== itemId);
    setItems(updatedItems);
    localStorage.setItem('riskOpportunityData', JSON.stringify(updatedItems));
  };

  const handleEditItem = (item) => {
    setEditingItem(item);
    setShowDataManager(true);
  };

  const handleItemClick = (item) => {
    handleEditItem(item);
  };

  return (
    <div className="App">
      <Header 
        onAddItem={() => setShowDataManager(true)}
        itemCount={filteredItems.length}
      />

      <div className="container">
        <div className="grid grid-cols-1 lg:grid-cols-4 gap-6 mb-6">
          <div className="lg:col-span-3">
            <RiskOpportunityHeatmap 
              items={filteredItems}
              onItemClick={handleItemClick}
            />
          </div>

          <div className="space-y-6">
            <FilterPanel 
              filters={filters}
              onFiltersChange={setFilters}
              items={items}
            />

            <ExportPanel 
              items={filteredItems}
            />
          </div>
        </div>
      </div>

      {showDataManager && (
        <DataManager
          item={editingItem}
          onSave={editingItem ? handleUpdateItem : handleAddItem}
          onCancel={() => {
            setShowDataManager(false);
            setEditingItem(null);
          }}
        />
      )}
    </div>
  );
}

export default App;
